<?php
require_once 'config.php';require_once __DIR__.'/includes/print_brand.php';$p=db();$id=(int)($_GET['id']??0);
if(!$id&&isset($_GET['area_id'],$_GET['date'])){$q=$p->prepare('SELECT id FROM audits WHERE area_id=? AND audit_date=? AND department="Office" ORDER BY id ASC LIMIT 1');$q->execute([(int)$_GET['area_id'],$_GET['date']]);$id=(int)$q->fetchColumn();}
$q=$p->prepare('SELECT au.*,a.area_name,a.group_name,a.unit_no FROM audits au JOIN areas a ON a.id=au.area_id WHERE au.id=? AND au.department="Office"');$q->execute([$id]);$a=$q->fetch();if(!$a)exit('ยังไม่มีข้อมูล Office สำหรับรายการนี้');
$q=$p->prepare('SELECT os.*,c.item_no,c.max_score,c.description FROM office_scores os JOIN office_criteria c ON c.id=os.criterion_id WHERE os.audit_id=? ORDER BY c.item_no');$q->execute([$id]);$rows=$q->fetchAll();
?><!doctype html><html lang="th"><meta charset="utf-8"><?=five_s_favicon_tags()?><title>5S Office</title><style>@page{size:A4 portrait;margin:5mm}body{font-family:Tahoma,Arial;font-size:8.5px}.head{display:flex;justify-content:space-between;border-bottom:2px solid #111;padding-bottom:7px}.title{font-size:16px;font-weight:bold}.aud{line-height:1.7}.aud b{display:inline-block;min-width:72px}table{width:100%;border-collapse:collapse;margin-top:8px}th,td{border:1px solid #555;padding:2px}th{background:#eee}.c{text-align:center}.no-print{margin:8px 0}@media print{.no-print{display:none}}</style><body><?=five_s_print_toolbar('history.php','กลับไปประวัติผลตรวจ')?><div class="head"><div><div style="margin-bottom:4px"><?=five_s_print_logo(26)?></div><div class="title">แบบตรวจประเมินมาตรฐานกิจกรรม 5 ส. (OFFICE)</div><div>กลุ่ม: <?=h($a['group_name'])?> / หน่วย: <?=h($a['unit_no'])?></div></div><div class="aud">วันที่: <?=h($a['audit_date'])?><br><b>ผู้ตรวจ 1:</b> <?=h($a['auditor'])?><br><b>ผู้ตรวจ 2:</b> <?=h($a['auditor2']??'')?><?php if(trim((string)($a['auditor3']??''))!==''): ?><br><b>ผู้ตรวจ 3:</b> <?=h($a['auditor3'])?><?php endif; ?></div></div>
<table><tr><th>ข้อ</th><th>หัวข้อประเมินมาตรฐาน Office</th><th>เต็ม</th><th>ผู้ตรวจ 1</th><th>ผู้ตรวจ 2</th><th>ผู้ตรวจ 3</th><th>เฉลี่ย</th><th>%</th><th>หมายเหตุ</th></tr>
<?php $sum=0;$max=0;foreach($rows as $r):$v1=$r['score1']??null;$v2=$r['score2']??null;$v3=$r['score3']??null;$avg=score_avg($v1,$v2,$v3);$isNa=$avg===null && str_starts_with((string)($r['note']??''),'N/A:');if($avg!==null){$sum+=(float)$avg;$max+=(float)$r['max_score'];}?><tr><td class="c"><?=h($r['item_no'])?></td><td><?=h($r['description'])?></td><td class="c"><?=h($r['max_score'])?></td><td class="c"><?=h($v1??'')?></td><td class="c"><?=h($v2??'')?></td><td class="c"><?=h($v3??'')?></td><td class="c"><?=$avg===null?($isNa?'N/A':''):number_format($avg,2)?></td><td class="c"><?=$avg===null?'':number_format(percent($avg,$r['max_score']),1)?></td><td><?=h($r['note'])?></td></tr><?php endforeach;?></table><h3>รวมคะแนน <?=number_format($sum,2)?> / <?=number_format($max,2)?> = <?=number_format($max?100*$sum/$max:0,1)?>% &nbsp; | &nbsp; เป้าหมาย <?=number_format(target_pct('Office'),1)?>%</h3><p><b>สรุป:</b> <?=h($a['overall_note'])?></p></body></html>
